        display: block;
        color: #f8fafc;
        font-weight: 700;
        line-height: 1.4;
      }

      .helper-text {
        margin: 0.35rem 0 0;
        color: #a5b4fc;
        font-size: 0.95rem;
        line-height: 1.5;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.25rem;
        background: linear-gradient(135deg, #38bdf8, #818cf8);
        color: #020617;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        box-shadow: 0 0.75rem 1.75rem rgba(56, 189, 248, 0.24);
