 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Consent Form</title>
     <style>
       :root {
         color-scheme: dark;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         background: #0f172a;
         color: #e5e7eb;
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         display: grid;
         place-items: center;
         padding: 1.5rem;
         background:
           radial-gradient(circle at top left, rgba(59, 130, 246, 0.22), transparent 32rem),
           linear-gradient(135deg, #020617 0%, #111827 58%, #0f172a 100%);
       }

       .app-shell {
         width: min(100%, 28rem);
       }

       .consent-card {
         border: 1px solid rgba(148, 163, 184, 0.2);
         border-radius: 1.25rem;
         padding: 2rem;
         background: rgba(15, 23, 42, 0.88);
         box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.45);
       }

       h1 {
         margin: 0 0 0.5rem;
         color: #f8fafc;
         font-size: clamp(1.75rem, 6vw, 2.25rem);
         line-height: 1.1;
       }

       .intro {
         margin: 0 0 1.5rem;
         color: #cbd5e1;
         line-height: 1.6;
       }

       .form-field {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.75rem;
         align-items: start;
         margin-bottom: 1.5rem;
         padding: 1rem;
         border: 1px solid rgba(148, 163, 184, 0.22);
         border-radius: 0.875rem;
         background: rgba(30, 41, 59, 0.72);
       }

       input[type="checkbox"] {
         width: 1.25rem;
         height: 1.25rem;
         margin: 0.15rem 0 0;
         accent-color: #38bdf8;
       }

       input[type="checkbox"]:focus-visible {
         outline: 3px solid rgba(56, 189, 248, 0.9);
         outline-offset: 3px;
       }

       label {
         display: block;
         color: #f8fafc;
         font-weight: 700;
         line-height: 1.4;
       }

       .helper-text {
         margin: 0.35rem 0 0;
         color: #a5b4fc;
         font-size: 0.95rem;
         line-height: 1.5;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.25rem;
         background: linear-gradient(135deg, #38bdf8, #818cf8);
         color: #020617;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         box-shadow: 0 0.75rem 1.75rem rgba(56, 189, 248, 0.24);
       }

       button:hover {
         transform: translateY(-1px);
       }

       button:focus-visible {
         outline: 3px solid #f8fafc;
         outline-offset: 4px;
       }
     </style>
   </head>
   <body>
     <main id="root" class="app-shell"></main>

     <script>
       function createElement(tagName, attributes = {}, children = []) {
         const element = document.createElement(tagName);

         Object.entries(attributes).forEach(([name, value]) => {
           if (name === "className") {
             element.className = value;
             return;
           }

           if (name === "htmlFor") {
             element.htmlFor = value;
             return;
           }

           if (typeof value === "boolean") {
             if (value) {
               element.setAttribute(name, "");
             }
             return;
           }

           element.setAttribute(name, value);
         });

         children.forEach((child) => {
           element.append(child);
         });

         return element;
       }

       function ConsentCheckbox() {
         return createElement("div", { className: "form-field" }, [
           createElement("input", {
             id: "terms-consent",
             name: "termsConsent",
             type: "checkbox",
             required: true,
             "aria-describedby": "terms-helper"
           }),
           createElement("div", {}, [
             createElement("label", { htmlFor: "terms-consent" }, [
               "I agree to the terms of use"
             ]),
             createElement("p", { id: "terms-helper", className: "helper-text" }, [
               "Required to continue with your submission."
             ])
           ])
         ]);
       }

       function ConsentForm() {
         return createElement("section", {
           className: "consent-card",
           "aria-labelledby": "form-title"
         }, [
           createElement("h1", { id: "form-title" }, ["Terms consent"]),
           createElement("p", { className: "intro" }, [
             "Please confirm your agreement before submitting the form."
           ]),
           createElement("form", {}, [
             ConsentCheckbox(),
             createElement("button", { type: "submit" }, ["Submit consent"])
           ])
         ]);
       }

       document.getElementById("root").append(ConsentForm());
     </script>
   </body>
 </html>

